class Graph:
    def __init__(self, vertices):
        self.vertices = vertices
        self.adj_list = {vertex: [] for vertex in range(vertices)}

    def add_edge(self, u, v):
        self.adj_list[u].append(v)

    def is_valid_path(self, start, end, path=[]):
        path = path + [start]
        if start == end:
            return True
        for node in self.adj_list[start]:
            if self.is_valid_path(node, end, path):
                return True
        return False

    def shortest_path(self, start, end):
        path = self.dfs(start, end)
        if path is None:
            return None
        return path

    def dfs(self, start, end):
        stack = [start]
        visited = set()
        parent = {node: None for node in range(self.vertices)}

        while stack:
            current = stack.pop()
            visited.add(current)

            if current == end:
                break

            for neighbor in self.adj_list[current]:
                if neighbor not in visited:
                    parent[neighbor] = current
                    stack.append(neighbor)

        path = self.reconstruct_path(start, end, parent)
        return path

    def reconstruct_path(self, start, end, parent):
        path = []
        while end:
            path.append(end)
            end = parent[end]
        if path:
            path.append(start)
            return path[::-1]
        return None

